// The spec of the postgres example, written again in each language and generated by its SDK, is the example's
// golden — byte for byte in Go and Java, as its own golden test reads it in Python: the spec says the pack whole,
// and each source says it as its language does.
func TestScaffoldRoundTrip(t *testing.T) {
	for _, ex := range []string{"postgres", "docker"} {
		t.Run(ex, func(t *testing.T) { roundTrip(t, ex) })
	}
}

func roundTrip(t *testing.T, ex string) {
	golden, err := filepath.Abs(filepath.Join("..", "..", "examples", ex, "golden", ex))
	if err != nil {
		t.Fatal(err)
	}
	spec, err := FromPack(golden)
	if err != nil {
		t.Fatal(err)
	}
	sdkPython, _ := filepath.Abs(filepath.Join("..", "..", "sdk", "python"))
	for _, lang := range Langs {
		t.Run(lang, func(t *testing.T) {
			var o Options
			switch lang {
			case Python:
				if _, err := exec.LookPath("python3"); err != nil {
					t.Skip("no python3")
				}
				t.Setenv("PYTHONPATH", sdkPython)
			case Java:
				classes := javaSDK(t)
				o.Classpath = classes
			}
			// a Go package is a package of a module: written inside this one
			dir := t.TempDir()
			if lang == Go {
				var err error
				if dir, err = os.MkdirTemp(".", "zz_scaffold_"); err != nil {
					t.Fatal(err)
				}
				t.Cleanup(func() { _ = os.RemoveAll(dir) })
				dir, _ = filepath.Abs(dir)
			}
			if _, err := Scaffold(spec, lang, dir, ScaffoldOptions{Templates: filepath.Join(golden, "templates")}); err != nil {
				t.Fatal(err)
			}
			out := t.TempDir()
			if err := Generate(context.Background(), dir, lang, out, o); err != nil {
				t.Fatalf("generate: %v", err)
			}
			// the Python SDK writes the same JSON with the keys of a node in another order: its own golden test reads it
			same(t, golden, filepath.Join(out, ex), lang == Python)
		})
	}
}

// javaSDK compiles the Java SDK, or skips when there is no javac.
func javaSDK(t *testing.T) string {
	t.Helper()
	if err := exec.Command("javac", "-version").Run(); err != nil {
		t.Skip("no javac that runs (macOS has a stub of it without a JDK)")
	}
	var srcs []string
	_ = filepath.WalkDir(filepath.Join("..", "..", "sdk", "java", "src", "main"), func(p string, e fs.DirEntry, _ error) error {
		if e != nil && !e.IsDir() && filepath.Ext(p) == ".java" {
			srcs = append(srcs, p)
		}
		return nil
	})
	classes := t.TempDir()
	if out, err := exec.Command("javac", append([]string{"--release", "21", "-d", classes}, srcs...)...).CombinedOutput(); err != nil {
		t.Fatalf("javac the SDK: %v\n%s", err, out)
	}
	return classes
}

// same compares two directories, file by file — a .json by what it says when asJSON.
func same(t *testing.T, want, got string, asJSON bool) {
	t.Helper()
	files := func(root string) map[string][]byte {
		out := map[string][]byte{}
		_ = filepath.WalkDir(root, func(p string, e fs.DirEntry, err error) error {
			if err == nil && !e.IsDir() {
				rel, _ := filepath.Rel(root, p)
				out[rel], _ = os.ReadFile(p)
			}
			return nil
		})
		return out
	}
	w, g := files(want), files(got)
	for name, b := range w {
		if gb, ok := g[name]; !ok {
			t.Errorf("%s: not written", name)
		} else if asJSON && filepath.Ext(name) == ".json" {
			var x, y any
			if json.Unmarshal(b, &x) != nil || json.Unmarshal(gb, &y) != nil || !reflect.DeepEqual(x, y) {
				t.Errorf("%s says another JSON:\nwant %s\ngot  %s", name, b, gb)
			}
		} else if !bytes.Equal(b, gb) {
			t.Errorf("%s differs:\nwant %s\ngot  %s", name, b, gb)
		}
	}
	for name := range g {
		if _, ok := w[name]; !ok {
			t.Errorf("%s: written, not in the golden", name)
		}
	}
}

// What a spec cannot say is refused before a line is written: a name of no language, a type of none, a formula on no
// field; a pack that holds another is not said by a spec yet.
func TestSpecRefuses(t *testing.T) {
	for name, s := range map[string]Spec{
		"no version":                     {Name: "x"},
		"a capital":                      {Name: "x", Version: "1", Fields: []Field{{Name: "PgPort", Type: TInteger}}},
		"a type of none":                 {Name: "x", Version: "1", Fields: []Field{{Name: "a", Type: "date"}}},
		"an empty object":                {Name: "x", Version: "1", Fields: []Field{{Name: "a", Type: TObject}}},
		"a list of nothing":              {Name: "x", Version: "1", Fields: []Field{{Name: "a", Type: TList}}},
		"twice":                          {Name: "x", Version: "1", Fields: []Field{{Name: "a", Type: TString}, {Name: "a", Type: TString}}},
		"a formula on none":              {Name: "x", Version: "1", Fields: []Field{{Name: "a", Type: TString}}, Compute: map[string]string{"/b": "1"}},
		"a rule of the root":             {Name: "x", Version: "1", Fields: []Field{{Name: "a", Type: TString}}, Rules: map[string][]packschema.Rule{"/": {{}}}},
		"a default of another type":      {Name: "x", Version: "1", Fields: []Field{{Name: "a", Type: TInteger, Default: 1.5}}},
		"a list default of another item": {Name: "x", Version: "1", Fields: []Field{{Name: "a", Type: TList, Items: TString, Default: []any{1.0}}}},
		"a group of none":                {Name: "x", Version: "1", Fields: []Field{{Name: "a", Type: TString, Group: "net"}}},
		"a param of no type":             {Name: "x", Version: "1", Actions: []Action{{Name: "go", Command: []string{"true"}, Params: []Param{{Name: "p", Type: "date"}}}}},
		"an enum of another type": {Name: "x", Version: "1", Actions: []Action{{Name: "go", Command: []string{"true"},
			Params: []Param{{Name: "p", Type: TInteger, Enum: []any{"one"}}}}}},
		"an enum of a boolean":         {Name: "x", Version: "1", Fields: []Field{{Name: "a", Type: TBoolean, Enum: []any{true}}}},
		"a field enum of another type": {Name: "x", Version: "1", Fields: []Field{{Name: "a", Type: TInteger, Enum: []any{"one"}}}},
		"a pattern of a number":        {Name: "x", Version: "1", Fields: []Field{{Name: "a", Type: TNumber, Pattern: "^1$"}}},
		"a pattern that is none":       {Name: "x", Version: "1", Fields: []Field{{Name: "a", Type: TString, Pattern: "(["}}},
		"a backquote in a pattern":     {Name: "x", Version: "1", Fields: []Field{{Name: "a", Type: TString, Pattern: "^`$"}}},
		"a minimum of a string":        {Name: "x", Version: "1", Fields: []Field{{Name: "a", Type: TString, Minimum: ptr(1.0)}}},
		"a minimum above maximum":      {Name: "x", Version: "1", Fields: []Field{{Name: "a", Type: TInteger, Minimum: ptr(2.0), Maximum: ptr(1.0)}}},
		"a length of an integer":       {Name: "x", Version: "1", Fields: []Field{{Name: "a", Type: TInteger, MaxLength: ptr(1)}}},
		"a default out of enum":        {Name: "x", Version: "1", Fields: []Field{{Name: "a", Type: TString, Default: "c", Enum: []any{"a", "b"}}}},
		"a default out of bounds":      {Name: "x", Version: "1", Fields: []Field{{Name: "a", Type: TInteger, Default: 0.0, Minimum: ptr(1.0)}}},
		"a default not matching":       {Name: "x", Version: "1", Fields: []Field{{Name: "a", Type: TString, Default: "B", Pattern: "^[a-z]+$"}}},
		"a default too long":           {Name: "x", Version: "1", Fields: []Field{{Name: "a", Type: TString, Default: "abc", MaxLength: ptr(2)}}},
		"an action twice":              {Name: "x", Version: "1", Actions: []Action{{Name: "go", Command: []string{"true"}}, {Name: "go", Command: []string{"true"}}}},
	} {
		if err := s.Check(); err == nil {
			t.Errorf("%s: no refusal", name)
		}
	}
	if _, err := FromPack(filepath.Join("..", "..", "examples", "openbao", "golden", "openbao")); err == nil {
		t.Error("a pack that holds another")
	}
}

func ptr[T any](v T) *T { return &v }

// A scaffold is written once: a second one into the same directory is refused before a file is written, and Force
// writes over them.
func TestScaffoldOnce(t *testing.T) {
	s := &Spec{Name: "kv", Version: "1", Fields: []Field{{Name: "port", Type: TInteger, Default: 6380.0}}}
	dir := t.TempDir()
	if _, err := Scaffold(s, Python, dir, ScaffoldOptions{}); err != nil {
		t.Fatal(err)
	}
	mine := []byte("# the author's code\n")
	if err := os.WriteFile(filepath.Join(dir, "kv.py"), mine, 0o644); err != nil {
		t.Fatal(err)
	}
	if err := os.Remove(filepath.Join(dir, "tests", "basic.yaml")); err != nil {
		t.Fatal(err)
	}
	if _, err := Scaffold(s, Python, dir, ScaffoldOptions{}); err == nil || !strings.Contains(err.Error(), "kv.py") {
		t.Fatalf("a second scaffold: %v", err)
	}
	if b, _ := os.ReadFile(filepath.Join(dir, "kv.py")); !bytes.Equal(b, mine) {
		t.Error("the author's code written over")
	}
	if _, err := os.Stat(filepath.Join(dir, "tests", "basic.yaml")); err == nil {
		t.Error("a file written by a refused scaffold")
	}
	if _, err := Scaffold(s, Python, dir, ScaffoldOptions{Force: true}); err != nil {
		t.Fatal(err)
	}
	if b, _ := os.ReadFile(filepath.Join(dir, "kv.py")); bytes.Equal(b, mine) {
		t.Error("Force wrote nothing over")
	}
}

// What a value may be — enum, pattern, bounds, lengths — is said the same in the three languages: each SDK writes the
// schema the Go one does, and the schema is read back as the spec.
func TestScaffoldConstraints(t *testing.T) {
	lo, hi, frac := 1.0, 65535.0, 0.5
	short, long := 1, 8
	spec := &Spec{Name: "kv", Version: "1.0.0", Fields: []Field{
		{Name: "level", Type: TString, Default: "info", Enum: []any{"debug", "info", "a,b"}},
		{Name: "port", Type: TInteger, Default: 6380.0, Minimum: &lo, Maximum: &hi},
		{Name: "ratio", Type: TNumber, Maximum: &frac},
		{Name: "mode", Type: TInteger, Enum: []any{1.0, 2.0}},
		{Name: "node", Type: TObject, Fields: []Field{
			{Name: "id", Type: TString, Required: true, Pattern: `^[a-z]{1,8}\d*$`, MinLength: &short, MaxLength: &long},
		}},
	}}
	schemas := map[string]string{}
	for _, lang := range Langs {
		t.Run(lang, func(t *testing.T) {
			var o Options
			switch lang {
			case Python:
				if _, err := exec.LookPath("python3"); err != nil {
					t.Skip("no python3")
				}
				sdkPython, _ := filepath.Abs(filepath.Join("..", "..", "sdk", "python"))
				t.Setenv("PYTHONPATH", sdkPython)
			case Java:
				o.Classpath = javaSDK(t)
			}
			dir := t.TempDir()
			if lang == Go {
				var err error
				if dir, err = os.MkdirTemp(".", "zz_scaffold_"); err != nil {
					t.Fatal(err)
				}
				t.Cleanup(func() { _ = os.RemoveAll(dir) })
				dir, _ = filepath.Abs(dir)
			}
			if _, err := Scaffold(spec, lang, dir, ScaffoldOptions{}); err != nil {
				t.Fatal(err)
			}
			out := t.TempDir()
			if err := Generate(context.Background(), dir, lang, out, o); err != nil {
				t.Fatalf("generate: %v", err)
			}
			b, err := os.ReadFile(filepath.Join(out, "kv", "schema.json"))
			if err != nil {
				t.Fatal(err)
			}
			schemas[lang] = string(b)
			if lang != Go {
				return
			}
			back, err := FromPack(filepath.Join(out, "kv"))
			if err != nil {
				t.Fatal(err)
			}
			if !reflect.DeepEqual(back.Fields, spec.Fields) {
				t.Errorf("read back:\n%+v\nwant\n%+v", back.Fields, spec.Fields)
			}
			for _, want := range []string{`"enum":["debug","info","a,b"]`, `"maximum":65535,"minimum":1`, `"maximum":0.5`, `"enum":[1,2]`,
				`"maxLength":8,"minLength":1,"pattern":"^[a-z]{1,8}\\d*$"`} {
				if !strings.Contains(string(b), want) {
					t.Errorf("no %s in\n%s", want, b)
				}
			}
		})
	}
	goSchema, ok := schemas[Go]
	if !ok {
		return
	}
	for lang, got := range schemas {
		var x, y any
		if json.Unmarshal([]byte(goSchema), &x) != nil || json.Unmarshal([]byte(got), &y) != nil || !reflect.DeepEqual(x, y) {
			t.Errorf("%s says another schema:\ngo   %s\n%-4s %s", lang, goSchema, lang, got)
		}
		if lang == Java && got != goSchema {
			t.Errorf("java: not byte for byte:\ngo   %s\njava %s", goSchema, got)
		}
	}
}

// A length that is no whole number is refused as it is read back, not cut to one.
func TestFromPackRefusesAFractionalLength(t *testing.T) {
	node := map[string]any{"properties": map[string]any{"id": map[string]any{"type": "string", "maxLength": 1.5}}}
	if _, err := (&Spec{}).fieldsFrom(node, "", map[string][]string{"": {"id"}}); err == nil || !strings.Contains(err.Error(), "not a whole number") {
		t.Errorf("maxLength 1.5: %v", err)
	}
}
